/* Scoped to this route by the compiler, so `.tally` here cannot reach a
   `.tally` anywhere else on the site. */
.tally {
  padding: 1rem;
  border: 1px solid var(--w-border);
  border-radius: 12px;
}

.runtime {
  font-size: .875rem;
  opacity: .7;
}

export default class {
  count = 6
  runtime = 'JavaScript, everywhere'

  doubled() {
    return this.count * 2
  }
}

export default class {
  count: number = 6
  runtime: string = 'TypeScript, everywhere'

  doubled(): number {
    return this.count * 2
  }
}

pub struct Companion {
    pub count: i32,
    pub runtime: &'static str,
}

impl Companion {
    pub fn new() -> Self {
        Self { count: 6, runtime: "Rust, linked into the app" }
    }

    pub fn doubled(&self) -> i32 {
        self.count * 2
    }
}

final class Companion {
  var count = 6
  let runtime = "Swift, compiled into the app"

  func doubled() -> Int { count * 2 }
}

class Companion {
  var count: Int = 6
  val runtime: String = "Kotlin, compiled into the APK"

  fun doubled(): Int = count * 2
}

public class Companion
{
    public int Count = 6;
    public string Runtime => "C#, published ahead of time";

    public int Doubled() => Count * 2;
}

import { OrderService } from '../../services/orders.js'

@Controller
export class OrdersController {
  // A route is thin on purpose: one request in, one call down, one response.
  static GET() {
    return { orders: new OrderService().list() }
  }
}

import { OrderRepository } from '../repositories/orders.js'

@Service
export class OrderService {
  // Injected rather than constructed inline, so a test supplies its own
  // repository without reaching for a module mock.
  constructor(repository = new OrderRepository()) {
    this.repository = repository
  }

  list() {
    return this.repository.all()
  }
}

@Repository
export class OrderRepository {
  // Owns storage and nothing else. A repository, a client and a delegate are
  // peers: none of them calls another.
  all() {
    return [{ sku: 'anvil', level: 4 }]
  }
}

